evidence.schema_rules:
CREATE OR REPLACE FUNCTION public.c3_evaluate_pac_schema_rules_v1(p_schema_key text, p_presented_pac jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_schema public.c3_pac_schema%rowtype;
  v_rule jsonb;
  v_rule_type text;
  v_missing jsonb := '[]'::jsonb;
  v_count integer;
  v_min integer;
  v_relations jsonb;
  v_path text[];
  v_actual jsonb;
  v_envpac public.c3_envpac%rowtype;
  v_env public.c3_environment%rowtype;
begin
  if p_presented_pac is null or jsonb_typeof(p_presented_pac) <> 'object' then
    return jsonb_build_object(
      'standing','HLD','reason','presented_pac_object_required',
      'rule_language_version','v1','unresolved',jsonb_build_array('presented_pac')
    );
  end if;

  select * into v_schema
  from public.c3_pac_schema
  where schema_key=p_schema_key
    and standing='active'
    and is_active=true;

  if not found or v_schema.pac_type is distinct from p_presented_pac->>'pac_type' then
    return jsonb_build_object(
      'standing','HLD','reason','active_schema_unresolved',
      'rule_language_version','v1','unresolved',jsonb_build_array('active_schema')
    );
  end if;

  if v_schema.required_fields ? 'contract_key' then
    return jsonb_build_object(
      'standing','HLD',
      'reason','nonweb3_contract_schema_not_admissible',
      'schema_key',v_schema.schema_key,
      'rule_language_version','v1',
      'unresolved',jsonb_build_array('contract_key:reserved_for_web3')
    );
  end if;

  v_relations := case
    when jsonb_typeof(p_presented_pac->'relations')='array'
      then p_presented_pac->'relations'
    else '[]'::jsonb
  end;

  for v_rule in
    select value from jsonb_array_elements(v_schema.required_relation_rules)
  loop
    if jsonb_typeof(v_rule) <> 'object' then
      v_missing := v_missing || jsonb_build_array('unsupported_required_relation_rule:non_object');
      continue;
    end if;

    v_rule_type := nullif(v_rule->>'rule_type','');

    if v_rule_type='presented_relation_count' then
      if nullif(v_rule->>'relation_type','') is null
         and nullif(v_rule->>'target_kind','') is null then
        v_missing := v_missing || jsonb_build_array('malformed_required_relation_rule:presented_relation_count');
        continue;
      end if;

      if v_rule ? 'min' then
        if coalesce(v_rule->>'min','') !~ '^[1-9][0-9]*$' then
          v_missing := v_missing || jsonb_build_array('malformed_required_relation_rule:min');
          continue;
        end if;
        v_min := (v_rule->>'min')::integer;
      else
        v_min := 1;
      end if;

      select count(*) into v_count
      from jsonb_array_elements(v_relations) r
      where (nullif(v_rule->>'relation_type','') is null
             or r.value->>'relation_type'=v_rule->>'relation_type')
        and (nullif(v_rule->>'target_kind','') is null
             or r.value->>'target_kind'=v_rule->>'target_kind');

      if v_count < v_min then
        v_missing := v_missing || jsonb_build_array(
          'required_relation:'||
          coalesce(v_rule->>'relation_type','*')||':'||
          coalesce(v_rule->>'target_kind','*')
        );
      end if;
    else
      v_missing := v_missing || jsonb_build_array(
        'unsupported_required_relation_rule:'||
        coalesce(v_rule_type,nullif(v_rule->>'rule',''),'untyped')
      );
    end if;
  end loop;

  for v_rule in
    select value from jsonb_array_elements(v_schema.conditional_rules)
  loop
    if jsonb_typeof(v_rule) <> 'object' then
      v_missing := v_missing || jsonb_build_array('unsupported_conditional_rule:non_object');
      continue;
    end if;

    v_rule_type := nullif(v_rule->>'rule_type','');

    if v_rule_type in ('envpac_metadata_equals','environment_metadata_equals') then
      if jsonb_typeof(v_rule->'path') is distinct from 'array'
         or jsonb_array_length(v_rule->'path')=0
         or not (v_rule ? 'expected')
         or exists (
           select 1
           from jsonb_array_elements_text(v_rule->'path') x
           where btrim(x.value)=''
         ) then
        v_missing := v_missing || jsonb_build_array('malformed_conditional_rule:'||v_rule_type);
        continue;
      end if;

      select array_agg(x.value order by x.ord)
        into v_path
      from jsonb_array_elements_text(v_rule->'path') with ordinality as x(value,ord);

      select * into v_envpac
      from public.c3_envpac
      where envpac_key=p_presented_pac->>'envpac_key'
        and is_effective=true;

      if not found then
        v_missing := v_missing || jsonb_build_array('conditional_rule:'||v_rule_type||':envpac_unresolved');
        continue;
      end if;

      if v_rule_type='envpac_metadata_equals' then
        v_actual := jsonb_extract_path(v_envpac.metadata,variadic v_path);
      else
        select * into v_env
        from public.c3_environment
        where env_key=v_envpac.env_key
          and is_active=true;

        if not found then
          v_missing := v_missing || jsonb_build_array('conditional_rule:environment_metadata_equals:environment_unresolved');
          continue;
        end if;

        v_actual := jsonb_extract_path(v_env.metadata,variadic v_path);
      end if;

      if v_actual is distinct from v_rule->'expected' then
        v_missing := v_missing || jsonb_build_array(
          'conditional_rule:'||v_rule_type||':'||
          array_to_string(v_path,'.')
        );
      end if;

    elsif v_rule_type='envpac_environment_class_equals' then
      if nullif(v_rule->>'expected','') is null then
        v_missing := v_missing || jsonb_build_array('malformed_conditional_rule:envpac_environment_class_equals');
        continue;
      end if;

      select ep.* into v_envpac
      from public.c3_envpac ep
      where ep.envpac_key=p_presented_pac->>'envpac_key'
        and ep.is_effective=true;

      if not found then
        v_missing := v_missing || jsonb_build_array('conditional_rule:envpac_environment_class_equals:envpac_unresolved');
        continue;
      end if;

      select * into v_env
      from public.c3_environment
      where env_key=v_envpac.env_key
        and is_active=true;

      if not found
         or v_env.environment_class is distinct from v_rule->>'expected' then
        v_missing := v_missing || jsonb_build_array('conditional_rule:envpac_environment_class_equals');
      end if;

    elsif v_rule_type='profile_subject_matches_owner' then
      if v_schema.pac_type <> 'ProfilePAC' then
        v_missing := v_missing || jsonb_build_array('malformed_conditional_rule:profile_subject_matches_owner');
      elsif p_presented_pac#>>'{profile,subject_type}' is distinct from p_presented_pac->>'owner_subject_type'
         or p_presented_pac#>>'{profile,subject_key}' is distinct from p_presented_pac->>'owner_subject_key' then
        v_missing := v_missing || jsonb_build_array('conditional_rule:profile_subject_matches_owner');
      end if;

    else
      v_missing := v_missing || jsonb_build_array(
        'unsupported_conditional_rule:'||
        coalesce(v_rule_type,nullif(v_rule->>'rule',''),'untyped')
      );
    end if;
  end loop;

  if jsonb_array_length(v_missing)>0 then
    return jsonb_build_object(
      'standing','HLD',
      'reason','schema_rules_unresolved',
      'schema_key',v_schema.schema_key,
      'rule_language_version','v1',
      'unresolved',v_missing
    );
  end if;

  return jsonb_build_object(
    'standing','PASS',
    'schema_key',v_schema.schema_key,
    'rule_language_version','v1',
    'unresolved','[]'::jsonb
  );
end $function$
